mapper.select:
SELECT msh.id, msh.tenant_code, msh.submit_id, msh.employee_id, IF(mu.nick_name IS NULL, mu.user_name,mu.nick_name) as employee_name, mu.user_name as employee_user_name, msh.adjusted_num, msh.product_seq, msh.product_code, msh.product_name, msh.product_unit, msh.operate_process_seq, msh.operate_process_code, msh.operate_process_name, msh.remark, msh.created_by, IF(mu2.nick_name IS NULL, mu2.user_name,mu2.nick_name) as created_by_name, msh.created_date FROM micro_settlement_history msh LEFT JOIN micro_user mu ON msh.tenant_code = mu.tenant_code AND msh.employee_id=mu.id LEFT JOIN micro_user mu2 ON msh.tenant_code = mu2.tenant_code AND msh.created_by=mu2.id
and msh.tenant_code = #{entity.tenantCode} and msh.submit_id = #{entity.submitId} and msh.employee_id = #{entity.employeeId} and msh.adjusted_num = #{entity.adjustedNum} and msh.product_seq = #{entity.productSeq} and msh.product_code = #{entity.productCode} and msh.product_name like concat('%', #{entity.productName}, '%') and msh.operate_process_seq = #{entity.operateProcessSeq}
and msh.operate_process_code = #{entity.operateProcessCode}
and msh.operate_process_name like concat('%',#{entity.operateProcessName},'%')
and msh.created_by = #{entity.createdBy}
order by msh.created_date desc

SELECT mu.id AS employeeId, IF( mu.nick_name IS NULL, mu.user_name, nick_name ) AS employeeName, mu.user_name AS employeeUserName FROM micro_settlement_history msh INNER JOIN micro_user mu ON msh.tenant_code = mu.tenant_code AND msh.employee_id = mu.id WHERE msh.remark IS NOT NULL AND msh.remark !='' and msh.employee_id = #{entity.employeeId} and msh.product_seq = #{entity.productSeq} and msh.operate_process_seq = #{entity.operateProcessSeq}
and ( mu.user_name like concat('%', #{searchKey}, '%') or mu.nick_name like concat('%', #{searchKey}, '%') )
GROUP BY mu.id ORDER BY mu.id

SELECT msh.employee_id as employeeId, msh.product_seq AS productSeq, MAX(mp.product_name) AS productName, MAX(mp.product_code) AS productCode, MAX(msh.product_unit) AS productUnit, msh.operate_process_seq AS operateProcessSeq, MAX(mpc.process_name) AS operateProcessName, MAX(mpc.process_code) AS operateProcessCode, ROUND(SUM(msh.adjusted_from_num-msh.adjusted_num),4) AS totalAdjustedNum FROM micro_settlement_history msh LEFT JOIN micro_process_common mpc ON msh.tenant_code = mpc.tenant_code AND msh.operate_process_seq = mpc.process_seq LEFT JOIN micro_product mp ON msh.tenant_code = mp.tenant_code AND msh.product_seq = mp.product_seq WHERE msh.remark IS NOT NULL AND msh.remark != ''
and msh.employee_id in
#{item}
and msh.product_seq = #{entity.productSeq} and msh.operate_process_seq = #{entity.operateProcessSeq}
GROUP BY msh.employee_id,msh.product_seq, msh.operate_process_seq ORDER BY msh.employee_id,msh.product_seq, msh.operate_process_seq

SELECT msh.employee_id, MAX(IF(mu.nick_name IS NULL, mu.user_name, mu.nick_name)) AS employee_name, mu.user_name AS employee_user_name, ROUND(SUM(msh.adjusted_num - msh.adjusted_from_num), 4) AS adjusted_num, msh.product_seq, MAX(msh.product_code) AS product_code, MAX(msh.product_name) AS product_name, MAX(msh.product_unit) AS product_unit, msh.operate_process_seq, MAX(msh.operate_process_code) AS operate_process_code, MAX(msh.operate_process_name) AS operate_process_name, MAX(msh.remark) AS remark, MAX(msh.created_by) AS created_by, MAX(IF(mu2.nick_name IS NULL, mu2.user_name, mu2.nick_name)) AS created_by_name, MAX(msh.created_date) AS created_date FROM micro_settlement_history msh LEFT JOIN micro_user mu ON msh.tenant_code = mu.tenant_code AND msh.employee_id=mu.id LEFT JOIN micro_user mu2 ON msh.tenant_code = mu2.tenant_code AND msh.created_by=mu2.id where msh.remark is not null and msh.remark != ''
and msh.tenant_code = #{entity.tenantCode}
and msh.employee_id = #{entity.employeeId}
and msh.product_seq = #{entity.productSeq}
and msh.operate_process_seq = #{entity.operateProcessSeq}
AND DATE_FORMAT(msh.created_date, '%y%m') = DATE_FORMAT(#{entity.createdDate}, '%y%m')
GROUP BY msh.employee_id, msh.product_seq, msh.operate_process_seq, msh.`version` ORDER BY msh.version DESC
